const item = $input.first().json;
const headers = item.headers || {};
const rawBody = item.body !== undefined ? item.body : item;
const payload =
  rawBody && typeof rawBody === 'object' && rawBody.body && typeof rawBody.body === 'object'
    ? rawBody.body
    : rawBody;

function respond(httpStatus, responseBody) {
  return [{ json: { respond: true, httpStatus, responseBody } }];
}

const secret = String($env.GREENHOUSE_OTP_WEBHOOK_SECRET || $env.APPLY_API_TOKEN || '').trim();
const authHeader = String(headers.authorization || headers.Authorization || '').trim();
const bearer = authHeader.match(/^Bearer\s+(.+)$/i)?.[1]?.trim() || '';

if (!secret || bearer !== secret) {
  return respond(403, { ok: false, message: 'unauthorized' });
}

const mailbox = String(payload.mailbox || 'or.shvartz70@gmail.com').trim();
const notBefore = String(payload.notBefore || '').trim();
const company = String(payload.company || '').trim();

const gmailQuery = [
  'newer_than:2d',
  '(from:greenhouse-mail.io OR from:greenhouse.io OR subject:"security code")',
  mailbox ? `to:${mailbox}` : '',
  company ? `"${company.replace(/"/g, '')}"` : '',
].filter(Boolean).join(' ');

const notBeforeMs = notBefore ? Date.parse(notBefore) : Date.now() - 15 * 60 * 1000;

return [{ json: { respond: false, gmailQuery, notBeforeMs } }];

const prep = $('Auth And Build Query').first().json;
const list = $input.first().json;
const messages = Array.isArray(list.messages) ? list.messages : [];
if (!messages.length) {
  return [{ json: { respond: true, httpStatus: 200, responseBody: { ok: false, message: 'no_messages', gmailQuery: prep.gmailQuery } } }];
}
return messages.slice(0, 8).map((m) => ({
  json: { respond: false, messageId: m.id, notBeforeMs: prep.notBeforeMs },
}));

function parseOtp(text) {
  const normalized = String(text || '').replace(/\s+/g, ' ');
  const patterns = [
    /security code field on your application:\s*([A-Za-z0-9]{8})\b/i,
    /verification code(?:\s+is)?[:\s]+([A-Za-z0-9]{8})\b/i,
    /security code[:\s]+([A-Za-z0-9]{8})\b/i,
    /enter the ([A-Za-z0-9]{8})-character code/i,
  ];
  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    const candidate = match?.[1]?.trim();
    if (candidate && /^[A-Za-z0-9]{8}$/.test(candidate)) return candidate;
  }
  return null;
}

function decodePart(part) {
  if (!part?.body?.data) return '';
  return Buffer.from(part.body.data, 'base64url').toString('utf8');
}

function collectBodies(part, out) {
  if (!part) return;
  out.push(decodePart(part));
  if (Array.isArray(part.parts)) for (const child of part.parts) collectBodies(child, out);
}

const prep = $('Auth And Build Query').first().json;
const notBeforeMs = prep.notBeforeMs;
const items = $input.all();

for (const item of items) {
  const full = item.json;
  const internalDate = Number(full.internalDate || 0);
  if (internalDate && internalDate < notBeforeMs - 10_000) continue;
  const hdrs = full.payload?.headers || [];
  const subject = hdrs.find((h) => h.name === 'Subject')?.value || '';
  const bodies = [];
  collectBodies(full.payload, bodies);
  const text = `${subject}\n${full.snippet || ''}\n${bodies.join('\n')}`;
  const code = parseOtp(text);
  if (code) {
    return [{ json: { respond: true, httpStatus: 200, responseBody: { ok: true, code, messageId: full.id } } }];
  }
}

return [{ json: { respond: true, httpStatus: 200, responseBody: { ok: false, message: 'no_code_yet' } } }];

